SELECT * FROM (
    SELECT ROWNUM AS rn, a.* FROM (
        SELECT 
            REPORT_ID, REPORT_DATE, TOTAL_FLIGHT_TIME, TOTAL_DETECT_COUNT,
            COMPLETION_RATE, CONFIRM_STATUS, PATROL_DATE, MOD_DATE, MEMBER_ID,
            ACTION_TAKEN, REMARK
        FROM PATROL_REPORT
        ORDER BY REPORT_ID DESC
    ) a WHERE ROWNUM <= #{endRow}
) WHERE rn >= #{startRow}

SELECT * FROM (
    SELECT ROWNUM AS rn, a.* FROM (
        SELECT
            REPORT_ID, REPORT_DATE, TOTAL_FLIGHT_TIME, TOTAL_DETECT_COUNT,
            COMPLETION_RATE, CONFIRM_STATUS, PATROL_DATE, MOD_DATE, MEMBER_ID,
            ACTION_TAKEN, REMARK
        FROM PATROL_REPORT
        WHERE CONFIRM_STATUS = '0'
        ORDER BY REPORT_ID DESC
    ) a WHERE ROWNUM <= #{endRow}
) WHERE rn >= #{startRow}

